# one-input factor specs: (kind, input) ; kind in E,R,L(u),Q(u^2),C(const),EL(exp(-a u)),Z(1/(1+a u))
def fac(kind,u,p):
    if kind=='E': return np.exp(-p*u**2)
    if kind=='R': return u**2/(1+p*u**2)
    if kind=='EL': return np.exp(-p*u)
    if kind=='Z': return 1/(1+p*u**2)
    if kind=='L': return u
    if kind=='Q': return u**2
    if kind=='C': return np.ones_like(u)
nonl={'E','R','EL','Z'}
specs=[]
for u in 'txv':
    for k in ['E','R','EL','Z','L','Q']:
        specs.append((k,u))
types=[]
for s in specs: types.append(((s,),))
for s1,s2 in itertools.combinations(specs,2):
    if s1[1]!=s2[1]: types.append(((s1,s2),))
types=[tt[0] for tt in types]
types=[tt for tt in types if not (len(tt)==2 and tt[0][0] in('L','Q') and tt[1][0] in('L','Q') and False)]
def tfunc(tt):
    npar=sum(1 for s in tt if s[0] in nonl)
    def f(p):
        out=np.ones_like(y); k=0
        for kind,u in tt:
            if kind in nonl: out=out*fac(kind,I[u],p[k]); k+=1
            else: out=out*fac(kind,I[u],0)
        return out
    return npar,f
TT=[(tt,)+tfunc(tt) for tt in types]
